<script lang="ts">import { uploadFeature } from '@fex-design/core/upload/features/upload'; import { UploadRoot, UploadTrigger, createUpload } from '@fex-design/svelte/primitive/upload'; import Button from '@fex-design/svelte/ui/button'; import { uploadBody, uploadServerUrl } from './api'; import DemoList from './demo-list.svelte'; import DemoSection from './demo-section.svelte'; const upload = createUpload({ accept: 'image/png,image/jpeg', multiple: true, beforeUpload(file) { if (!['image/png', 'image/jpeg'].includes(file.type)) throw new Error(`“${file.name}”不是 JPEG 或 PNG 图片。`); return file }, features: [uploadFeature({ request: ({ file, signal, onProgress }) => uploadBody(`${uploadServerUrl}/upload`, file, { fileName: file.name, signal, onProgress }) })] })</script>
<DemoSection title="文件类型与上传前处理" description="原生文件选择器通过 accept 筛选 JPEG/PNG，beforeUpload 对所有入口统一校验；校验失败会保留文件并展示具体错误。"><UploadRoot controller={upload}><UploadTrigger>{#snippet children(value)}<Button {...value.props}>选择 JPEG 或 PNG</Button>{/snippet}</UploadTrigger><DemoList /></UploadRoot></DemoSection>
